<template>
  <div class="day-buy" >
    <div class="mescroll" ref="pageMScroll">
      <div class="scroll-wrapper">
        <div class="img-box" v-if="headImg" :style="imgStyle"><img :src="headImg" alt=""></div>
        <ul class="list">
          <li class="item" v-for="(item, index) in list" :key="index" @click="checkGoodsDetail(item.goods_id)">
            <div class="goods-img">
              <img class="img" :src="item.image" alt="">
              <span class="icon txt-icon new-user">新人专享</span>
            </div>
            <div class="goods-title">{{ item.limit_buy == 0 ? '' : '【限购'+item.limit_buy+'份】' }}{{item.name}}</div>
            <div class="price-box">
              <div>
                <div>
                  <span class="now now-icon main-color-font">¥</span>
                  <span class="now main-color-font">{{item.price}}</span>
                  <span class="old">¥{{item.old_price}}</span>
                </div>
                <div class="num">已拼{{item.sell_count}}件</div>
              </div>
              <AddToCart v-if="item.stock_status == 0 && item.is_no_start == 0 && item.limit_buy_status == 0 " type="middle" :goodsId="item.goods_id"/>
            </div>
            <div class="close-buy" v-if="item.stock_status == 1 || item.is_no_start == 1 || item.limit_buy_status == 1 ">
              <div class="icon-box">
                <div class="icon" v-if=" item.stock_status == 1 ">已抢光</div>
                <div class="icon" v-else-if=" item.is_no_start == 1 || item.limit_buy_status == 1">未开始</div>
              </div>
            </div>
          </li>
        </ul>
      </div>
    </div>
    <div class="cart-icon" @click="openCart">
      <i class="icon iconfont">&#xe607;</i>
      <span class="total-num" v-if="totalNum > 0 && totalNum <= 99">{{totalNum}}</span>
      <span class="total-num" v-if="totalNum > 99">99+</span>
    </div>
  </div>
</template>

<script>
import MeScroll from 'mescroll.js'
import PubSub from 'pubsub-js'
import AddToCart from '../../components/AddToCart/AddToCart'
export default {
  name: 'DayBuy',
  data () {
    return {
      list: [], // 活动列表
      leader_id: '',
      pageScroll: '',
      page: 1,
      isComplete: false,
      imgStyle: '',
      totalNum: 0,
      headImg: '' // 顶部图片
    }
  },
  created () {
    this.leader_id = this.$util.storage.get('leader_id')
    this.initialScroll()

    this.imgStyle = `height:${parseInt(document.documentElement.clientWidth * 240 / 640)}px`

    let obj = this.$global.goodsNumObj
    if (obj.totalNum) {
      this.totalNum = obj.totalNum
    }
    // 订阅购物车数量变化
    PubSub.subscribe('cartInfo', (event, data) => {
      this.totalNum = data.num
    })
  },
  methods: {
    // 跳转到购物车
    openCart () {
      this.$router.push('/cart')
    },
    // 查看商品详情
    checkGoodsDetail (id) {
      this.$router.push({ path: '/goods', query: { goodsId: id, leaderId: this.leader_id } })
    },
    async getDetail () {
      let param = {
        page: this.page,
        leader_id: this.leader_id
      }
      let res = await this.$api.getNewUserGoods(param)
      if (!res) return
      if (!this.headImg) {
        this.headImg = res.img
      }
      this.list = this.list.concat(res.goods)
      if (res.goods.length < 20) {
        this.isComplete = true
      } else {
        this.page++
      }
      this.pageScroll.endSuccess(res.goods.length, !this.isComplete)
    },
    // 初始化滚动插件
    initialScroll () {
      let _this = this
      this.$nextTick(function () {
        this.pageScroll = new MeScroll(this.$refs.pageMScroll, {
          down: {
            isLock: true
          },
          up: {
            callback: _this.getDetail,
            lazyLoad: {
              use: true
            },
            htmlNodata: '<p class="upwarp-nodata">已经到底了...</p>',
            noMoreSize: 10
          }
        })
      })
    }
  },
  components: {
    AddToCart
  }
}
</script>

<style lang="stylus" scoped>
  .day-buy
    background #f8f8f8
    height 100%
    box-sizing border-box
    position relative
    .scroll-wrapper
      padding-bottom 30px
      .img-box
        width 100%
        overflow hidden
        img
          width 100%
          height 100%
          object-fit cover
      .list
        flexbox()
        flex-wrap wrap
        padding 0 15px 0
        margin-top 15px
        .item
          background #fff
          padding 12px
          margin-bottom 10px
          width calc(50% - 5px)
          border-radius 5px
          box-sizing border-box
          position relative
          &:nth-child(odd)
            margin-right 5px
          &:nth-child(even)
            margin-left 5px
          .goods-img
            width 100%
            padding-top 100%
            font-size 0
            position relative
            .img
              position absolute
              top 0
              left 0
              width 100%
              height 100%
              object-fit cover
            .icon
              position absolute
              top 0
              left 0
              width 30px
              height 30px
              color #fff
              font-size 12px
              overflow hidden
              flexbox()
              align-items center
              justify-content center
              &.txt-icon.new-user
                box-sizing border-box
                padding-left 2px
                background -webkit-linear-gradient(top, #ff9204, #fe4022)
          .goods-title
            font-size 12px
            margin-top 5px
            line-height 1.5
            height 36px
            ellipsis(2)
          .price-box
            margin-top 10px
            flexbox()
            justify-content space-between
            align-items center
            line-height 1.3
            .now
              font-size 16px
              font-weight bold
              color $color-main
              margin-right 5px
            .now-icon
              margin-right 0
              font-size 12px
            .old
              color #999999
              text-decoration line-through
            .num
              font-size 12px
              color #999999
          .close-buy
            position absolute
            top 0
            left 0
            right 0
            bottom 0
            background rgba(255, 255, 255, .4)
            padding 40px
            .icon-box
              width 100%
              padding-top 100%
              position relative
              .icon
                position absolute
                top 0
                left 0
                right 0
                bottom 0
                background rgba(0, 0, 0, .5)
                color #fff
                border-radius 50%
                flexbox()
                justify-content center
                align-items center
                font-size 16px
    .cart-icon
      position absolute
      bottom 20px
      left 20px
      width 40px
      height 40px
      text-align center
      font-weight 500
      border-radius 50%
      background rgba(0, 0, 0, .6)
      color #fff
      .icon
        font-size 24px
        line-height 40px
      .total-num
        position absolute
        right 0
        top 0
        background red
        color #fff
        padding 2px
        min-width 14px
        text-align center
        box-sizing border-box
        border-radius 8px
        font-size 10px
</style>
